const body = pm.response.json();
if (body.accessToken) {
  pm.environment.set('access_token', body.accessToken);
  console.log('access_token 已写入，长度', body.accessToken.length);
}
if (body.refreshToken) {
  console.log('注意：上游轮换了 refreshToken，请更新环境变量');
}

